#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat cats[3] = {
        {"张三", {f1}},
        {"李四", {f2}},
        {"计算机", {f3}}
    };
    int total = 0;

    for (int i = 0; i < 3; i++) {
        printf("%s 处理了 %d 条\n", cats[i].name, cats[i].fish);
        total = total + cats[i].fish;
    }
    printf("一共 %d 条\n", total);
    return 0;
}
